    private boolean readNotification(Intent intent){
        if(!"com.codexpane.OPEN_CHAT".equals(intent.getAction())||intent.getBooleanExtra("paneflow.notificationConsumed",false))return false;
        String target=intent.getStringExtra("computerId"),thread=intent.getStringExtra("threadId");String destination=intent.getStringExtra("consoleRoute");notificationRoute=Arrays.asList("tasks","queue","approvals").contains(destination)?destination:"chat";
        // Preserve launch action/data/component/categories for Activity lifecycle identity.
        // Only the one-shot navigation payload is consumed, including across recreation.
        Intent consumed=new Intent(launchIdentity);consumed.removeExtra("computerId");consumed.removeExtra("threadId");consumed.removeExtra("consoleRoute");consumed.putExtra("paneflow.notificationConsumed",true);setIntent(consumed);
        if(target!=null&&computers.find(target)==null){notificationThread="";Toast.makeText(this,"这台电脑已移除",Toast.LENGTH_SHORT).show();return false;}
        if(target!=null)connection=computers.select(target);
        notificationThread="chat".equals(notificationRoute)&&thread!=null?thread:"";return true;
    }
    @Override protected void onNewIntent(Intent i){super.onNewIntent(i);saveInputs();setIntent(i);resetTransient();boolean opened=readNotification(i);loadInputs();observe();if(opened){navigate(notificationRoute);if("chat".equals(notificationRoute)&&!notificationThread.isEmpty()&&online()&&connection.supports("independentSessions")){String target=notificationThread;notificationThread="";openThread(target);}}else navigate(connection.paired()?"tasks":"welcome");}
    private void observe(){for(NativeConnection c:computers.all())if(observed.add(c))c.add(this);}

    @Override protected void onResume(){super.onResume();computers.foreground(true);observe();if(computers.anyBackground())try{NativeMessagingService.ensure(this);}catch(Exception e){Toast.makeText(this,"后台服务暂不可用，前台连接继续",Toast.LENGTH_LONG).show();}render();}
    @Override protected void onStop(){if(dictation!=null)dictation.close();saveInputs();computers.foreground(false);super.onStop();}
