    @Override public void onBackPressed(){if(Arrays.asList("queue","queueNew","approvals","taskDetail","templates").contains(route)){navigate("tasks");return;}if("computers".equals(route)){navigate(computerReturnRoute);return;}if("chat".equals(route)||"new".equals(route))navigate(lastTab);else if("notifications".equals(route)||"connection".equals(route)||"diagnostics".equals(route)||"computers".equals(route)||"updates".equals(route)||"usage".equals(route))navigate("settings");else if("pair".equals(route)||"verify".equals(route)){connection.cancelPairing();pairingInProgress=false;navigate(connection.paired()?"settings":computers.all().size()>1?"computers":"welcome");}else if("sessions".equals(route)||"settings".equals(route))navigate("tasks");else super.onBackPressed();}
    private void loadInputs(){drafts.clear();unconfirmed.clear();pendingText.clear();pendingThreads.clear();JSONObject ds=connection.local.section("drafts"),uc=connection.local.section("unconfirmed");for(Iterator<String> it=ds.keys();it.hasNext();){String k=it.next();drafts.put(k,ds.optString(k));}for(Iterator<String> it=uc.keys();it.hasNext();){String k=it.next();unconfirmed.put(k,uc.optString(k));}JSONObject form=connection.local.section("newForm");newDirectory=form.optString("cwd");newPrompt=form.optString("text");newModel=form.optString("model");newEffort=form.optString("effort");}
    private void persistInputs(){try{connection.local.save("drafts",new JSONObject(drafts));connection.local.save("unconfirmed",new JSONObject(unconfirmed));connection.local.save("newForm",NativeConnection.obj("cwd",newDirectory,"text",newPrompt,"model",newModel,"effort",newEffort));}catch(Exception e){Toast.makeText(this,"本机保存失败，输入尚未持久保存",Toast.LENGTH_LONG).show();}}
