    private void resetTransient(){for(Dialog dialog:new ArrayList<>(dialogs))dialog.dismiss();dialogs.clear();handler.removeCallbacks(persistDraft);composer=null;newCwd=null;newText=null;chatList=null;chatAdapter=null;displayedThread="";displayedTurn="";pendingNavigate="";pendingOpenRequest="";pendingNew="";pendingFork="";pendingText.clear();pendingThreads.clear();restoringAnchor="";}
    private void selectComputer(NativeConnection next){if(wide&&tabletScroll!=null&&connection.computerId.equals(tabletScrollComputer))connection.historyScrollY=tabletRestoreY>=0?tabletRestoreY:tabletScroll.getScrollY();String destination="computers".equals(route)?computerReturnRoute:"tasks";if(!wide&&"sessions".equals(route)&&scroll!=null)connection.historyScrollY=scroll.getScrollY();saveInputs();resetTransient();connection=computers.select(next.computerId);loadInputs();query="";sessionLimit=5;notificationThread="";observe();computers.foreground(true);navigate(connection.paired()?destination:"pair");}
