    private void saveReading(){if(!restoringAnchor.isEmpty()||chatList==null||chatAdapter==null||displayedThread.isEmpty()||chatList.getChildCount()==0)return;int pos=chatList.getFirstVisiblePosition();String id=pos>0&&pos<=chatAdapter.items.length()?chatAdapter.items.optJSONObject(pos-1).optString("id"):"";try{JSONObject all=new JSONObject(connection.local.section("reading").toString());all.put(displayedThread,NativeConnection.obj("id",id,"position",pos,"top",chatList.getChildAt(0).getTop()));connection.local.save("reading",all);}catch(Exception ignored){}}

