    private void build(){
        if(dictation!=null)dictation.close();attachmentDrafts=null;jumpLatest=null;foldHistory=null;usageContent=null;usageKey="";
        if(updater!=null)updater.detach();if(taskConsole!=null)taskConsole.detach();root.removeAllViews();chatList=null;chatAdapter=null;historyButton=null;composer=null;search=null;pairInput=null;newCwd=null;newText=null;title=null;state=null;modelLabel=null;counts=null;listFooter=null;loadMoreButton=null;send=null;addAttachment=null;mic=null;composerReadOnly=false;createButton=null;messages=null;list=null;banner=null;contentKey="";listKey="";
        wide=wideScreen()&&connection.paired()&&!Arrays.asList("welcome","pair","verify").contains(route);
        tabletThreads=null;tabletStatus=null;tabletKey="";tabletScroll=null;tabletRestoreY=-1;
        body=ui.column();
        if(wide)buildTabletShell();else root.addView(body,new LinearLayout.LayoutParams(-1,0,1));
        switch(route){case "usage":usagePage();break;case "updates":updater.mount(body);break;case "tasks":case "queue":case "queueNew":case "approvals":case "taskDetail":case "templates":taskConsole.mount(body,route);break;case "welcome":welcome();break;case "pair":pairPage();break;case "verify":verification();break;case "sessions":if(!wide)threadList(false);break;case "chat":chat();break;case "new":newPage();break;case "settings":settings();break;case "connection":connectionPage();break;case "notifications":notifications();break;case "computers":computerPage();break;case "diagnostics":diagnosticsPage();break;default:threadList("tasks".equals(route));}
        if(!wide&&Arrays.asList("tasks","sessions","settings").contains(route))tabs();render();
    }
