    private void send(){if(!writable())return;if(!displayedThread.equals(threadId())||!pendingNavigate.isEmpty()){render();error("会话已切换，请核对输入后发送");return;}String text=composer.getText().toString().trim();JSONArray attachmentIds;try{attachmentIds=attachments.attachmentIds(connection,displayedThread);}catch(Exception e){error(e.getMessage());return;}if(text.isEmpty()&&attachmentIds.length()==0)return;if(text.length()>20000){error("消息超过 20000 字符，请分段发送");return;}try{String id=connection.command(NativeConnection.obj("type","turn.send","threadId",displayedThread,"text",text,"attachmentIds",attachmentIds));attachments.sent(connection,displayedThread,id);pendingText.put(id,text);pendingThreads.put(id,displayedThread);composer.setText("");drafts.put(displayedThread,"");persistInputs();send.setEnabled(false);hideKeyboard();}catch(Exception e){error(e.getMessage());}}
    private String command(JSONObject value){try{return connection.command(value);}catch(Exception e){error(e.getMessage());return null;}}
    @Override public void changed(JSONObject event){if(taskConsole!=null)taskConsole.changed(event);if(event.has("computerId")&&!connection.computerId.equals(event.optString("computerId"))){if("computers".equals(route))build();return;}String type=event.optString("type");
        if("chat".equals(notificationRoute)&&!notificationThread.isEmpty()&&connection.authenticated&&connection.supports("independentSessions")){String target=notificationThread;notificationThread="";openThread(target);}

        if("command.result".equals(type)&&"usage.get".equals(event.optString("commandType"))){if("usage".equals(route))renderUsage();return;}
        if("command.result".equals(type)){String id=event.optString("requestId"),text=pendingText.remove(id),destination=pendingThreads.remove(id);boolean ok=event.optBoolean("ok");
            boolean opening=id.equals(pendingOpenRequest)&&!pendingOpenRequest.isEmpty();
            if(opening){String target=pendingNavigate;pendingOpenRequest="";pendingNavigate="";if(ok&&target.equals(threadId()))navigate("chat");else if(ok)error("会话选择已变化，请从列表重新打开目标会话。");}
            if(event.optBoolean("backgroundSelectionRestore")){if(!ok)Toast.makeText(this,"上次会话暂时无法恢复，请从会话列表重新选择",Toast.LENGTH_LONG).show();return;}
            if("thread.open".equals(event.optString("commandType"))&&!opening)return;
            if(!ok)restoringAnchor="";if(text!=null&&!ok&&!connection.local.section("requests").has(id))restoreDraft(destination,text);if(id.equals(pendingNew)){pendingNew="";if(ok){newPrompt="";newDirectory="";if(newText!=null)newText.setText("");if(newCwd!=null)newCwd.setText("");navigate("chat");}else if(createButton!=null)createButton.setText("开始会话");}if(id.equals(pendingFork)){pendingFork="";if(ok)navigate("chat");}if(!ok){error(event.optString("message","操作未完成"));}}
        if("connection".equals(type)&&!connection.authenticated){connection.historyRequest="";boolean uncertain=!pendingText.isEmpty()||!pendingNew.isEmpty()||!pendingFork.isEmpty();for(Map.Entry<String,String> e:pendingText.entrySet())if(!connection.local.section("requests").has(e.getKey()))restoreDraft(pendingThreads.get(e.getKey()),e.getValue());pendingText.clear();pendingThreads.clear();pendingNew="";pendingFork="";pendingNavigate="";pendingOpenRequest="";if(createButton!=null)createButton.setText("开始会话");if(uncertain)Toast.makeText(this,"操作结果尚未确认，输入已保留。请先核对历史，避免重复操作。",Toast.LENGTH_LONG).show();}
        if("chat".equals(route)&&!displayedThread.equals(threadId()))renderChat();if(!scheduled){scheduled=true;handler.postDelayed(()->{scheduled=false;if(!isFinishing()&&connection.visible)render();},100);}
    }
    private void restoreDraft(String destination,String text){if(destination==null)return;String previous=unconfirmed.getOrDefault(destination,"");unconfirmed.put(destination,previous+(previous.isEmpty()?"":"\n\n")+text);}
