    static String usageNumber(JSONObject data,String key){Object value=data.opt(key);if(!(value instanceof Number))return "未提供";double n=((Number)value).doubleValue();if(!Double.isFinite(n)||n<0||n>9007199254740991d)return "未提供";return java.text.NumberFormat.getIntegerInstance(Locale.CHINA).format(((Number)value).longValue());}
    static String usageWindow(long minutes){if(minutes<=0)return "额度窗口";if(minutes==10080)return "每周额度";if(minutes%1440==0)return (minutes/1440)+" 天额度";if(minutes%60==0)return (minutes/60)+" 小时额度";return minutes+" 分钟额度";}
    private void renderUsage(){
        if(usageContent==null)return;
        JSONObject data=connection.usage;String key=connection.computerId+connection.name()+online()+connection.supports("usageSummary")+connection.usageRequest+connection.usageError+data.toString();if(key.equals(usageKey))return;usageKey=key;
        int y=scroll.getScrollY();usageContent.removeAllViews();LinearLayout c=usageContent;
        c.addView(ui.text(connection.name(),14,PaneUi.MUTED));ui.gap(c,16);
        if(!online()){c.addView(ui.text("电脑离线，无法刷新；以下为上次读取的数据。",14,PaneUi.AMBER));ui.gap(c,12);}
        else if(!connection.supports("usageSummary")){c.addView(ui.text("电脑需升级后才能查看用量管理。",14,PaneUi.AMBER));ui.gap(c,12);}
        if(!connection.usageError.isEmpty()){c.addView(ui.text(connection.usageError,14,PaneUi.AMBER));ui.gap(c,12);}
        JSONArray windows=data.optJSONArray("windows");
        if(data.optBoolean("limitsAvailable")&&windows!=null&&windows.length()>0){for(int i=0;i<windows.length();i++){JSONObject w=windows.optJSONObject(i);if(w==null)continue;double used=w.optDouble("usedPercent",Double.NaN);if(!Double.isFinite(used)||used<0)continue;LinearLayout card=ui.card();ui.pad(card,16,16);card.addView(ui.heading(usageWindow(w.optLong("windowMinutes",0)),18));String meter=w.optString("name","").replace(" · 主窗口","").replace(" · 次窗口","");if(!meter.isEmpty()&&!"codex".equalsIgnoreCase(meter)){ui.gap(card,8);card.addView(ui.text(meter,12,PaneUi.MUTED));}ui.gap(card,12);card.addView(ui.heading(String.format(Locale.CHINA,"剩余 %.1f%%",Math.max(0,100-used)),30));ui.gap(card,6);card.addView(ui.text(String.format(Locale.CHINA,"已用 %.1f%%",used),14,PaneUi.MUTED));ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(1000);bar.setProgress((int)Math.min(1000,used*10));bar.setProgressTintList(android.content.res.ColorStateList.valueOf(used>=90?PaneUi.AMBER:PaneUi.BLUE));ui.gap(card,10);card.addView(bar,new LinearLayout.LayoutParams(-1,ui.dp(6)));ui.gap(card,10);long reset=w.optLong("resetsAt",0);card.addView(ui.text(reset>0?"重置时间："+usageTime(reset*1000):"重置时间未提供",14,PaneUi.INK));c.addView(card);ui.gap(c,12);}}
        else {c.addView(ui.text(data.optString("limitsError",data.length()==0?"点击刷新读取额度":"账户未提供可用额度窗口"),14,PaneUi.MUTED));ui.gap(c,12);}
        ui.gap(c,8);c.addView(ui.text("更新于 "+usageTime(data.optLong("updatedAt",0)),12,PaneUi.MUTED));ui.gap(c,14);Button refresh=ui.primary(connection.usageRequest.isEmpty()?"刷新用量":"正在读取…",this::refreshUsage);refresh.setEnabled(online()&&connection.supports("usageSummary")&&connection.usageRequest.isEmpty());refresh.setAlpha(refresh.isEnabled()?1f:.45f);c.addView(refresh);scroll.post(()->scroll.scrollTo(0,y));
    }
