    private void confirmStop(){if(officialControl()){error("官方控制通道暂不支持停止，请在官方桌面端处理");return;}if(!writable())return;if(!displayedThread.equals(threadId())||turnId().isEmpty()){error("当前没有可停止的任务，请核对会话状态");return;}final String selected=displayedThread,turn=displayedTurn;LinearLayout c=ui.column();c.addView(ui.text(connection.snapshot.optString("activeThreadTitle"),16,PaneUi.INK));ui.gap(c,12);c.addView(ui.text("已完成的修改会保留。",14,PaneUi.MUTED));ui.gap(c,24);Dialog d=sheet("停止当前任务？",c);c.addView(ui.button("停止任务",PaneUi.RED,Color.WHITE,()->{d.dismiss();if(!writable())return;if(!selected.equals(threadId())||!turn.equals(turnId())){error("会话或任务已变化，请重新核对");return;}command(NativeConnection.obj("type","turn.interrupt","threadId",selected,"turnId",turn));}));ui.gap(c,10);c.addView(ui.button("继续运行",PaneUi.BG,PaneUi.BLUE,d::dismiss));}
