    private boolean approvalCurrent(JSONObject item,String thread){if(readOnly()||officialControl()||!thread.equals(threadId()))return false;JSONArray items=connection.snapshot.optJSONArray("items");if(items!=null)for(int i=0;i<items.length();i++){JSONObject current=items.optJSONObject(i);if(current!=null&&"approval".equals(current.optString("kind"))&&item.optString("id").equals(current.optString("id"))&&item.optInt("version")==current.optInt("version"))return true;}return false;}
